-- Additive only: persist WeChat prepay mapping and successful gateway transactions.
CREATE TABLE IF NOT EXISTS "__PREFIX__shop_payment_transaction" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "payment_sn" varchar(64) NOT NULL UNIQUE,
  "order_id" bigint NOT NULL,
  "order_sn" varchar(64) NOT NULL,
  "channel" varchar(30) NOT NULL,
  "channel_transaction_id" varchar(100) NOT NULL DEFAULT '',
  "amount" numeric(12,2) NOT NULL,
  "status" varchar(30) NOT NULL DEFAULT 'CREATED',
  "request_json" json DEFAULT NULL,
  "callback_json" json DEFAULT NULL,
  "paid_at" bigint DEFAULT NULL,
  "createtime" bigint NOT NULL,
  "updatetime" bigint DEFAULT NULL,
  UNIQUE ("channel","channel_transaction_id")
);
CREATE INDEX IF NOT EXISTS "__PREFIX__payment_tx_order_status" ON "__PREFIX__shop_payment_transaction" ("order_id","status");
